#!/usr/bin/env python3
"""Standalone redacted review; renders captured facts only, no audio playback."""
import html,json,pathlib
HERE=pathlib.Path(__file__).resolve().parent;E=HERE/'evidence';r=json.loads((E/'review.json').read_text());checks=r['checks'];passed=sum(x['pass'] for x in checks)
rows=''.join('<tr><td>'+html.escape(x['name'])+'</td><td class="'+('pass' if x['pass'] else 'fail')+'">'+('Pass' if x['pass'] else 'Fail')+'</td><td>'+html.escape(x['scope'])+'</td></tr>' for x in checks)
links=''.join('<li><a href="'+html.escape(p.name)+'">'+html.escape(p.name)+'</a></li>' for p in sorted(E.glob('*.json')))
profile=html.escape(json.dumps(r['profile'],indent=2));guide=html.escape((HERE/'README.md').read_text());unverified=''.join('<li>'+html.escape(x)+'</li>' for x in r['not_qualified'])
attempt=json.loads((E/'attempt.json').read_text()) if (E/'attempt.json').exists() else {'status':'captured staged experiments'}
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Qoda · ALSA handoff qualification</title><style>body{margin:0;background:#121c16;color:#e6eee6;font:16px/1.65 system-ui}main{max-width:1100px;margin:auto;padding:48px 24px}h1{font-size:clamp(30px,5vw,48px);line-height:1.15}.eyebrow,a,.pass{color:#bedf9a}.fail{color:#e9ad93}p{max-width:82ch;color:#becdbf}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:12px;margin:28px 0}.card{padding:20px;background:#1d2c21;border-radius:10px}.metric{display:block;font-size:27px;color:#cce8ac}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #344439;text-align:left;vertical-align:top}td:last-child{color:#b7c8bb;font-size:14px}.note{border-left:3px solid #d7b973;background:#2c291d;padding:18px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#1b281f;padding:18px;font-size:13px}h2{margin-top:36px}</style><main><div class="eyebrow">QODA / REAL ALSA DIGITAL HANDOFF</div><h1>Native payload measured.<br>Downstream fidelity stays unverified.</h1><p>Selected built-in speaker PCM, direct ALSA hw route. __PASSED__/__TOTAL__ reviewed scoped conditions pass. This is a throwaway prototype qualification, not an all-pass claim for every retained observation or the future production player.</p><p>Latest capture workflow: <b>__ATTEMPT__</b></p><div class="cards"><div class="card"><b class="metric">48 kHz</b>only qualified native rate here</div><div class="card"><b class="metric">S16 / stereo</b>actual hardware format</div><div class="card"><b class="metric">0 LSB</b>observed supported gain error</div><div class="card"><b class="metric">No conversion</b>unsupported formats blocked</div></div><p class="note">Boundary: PCM accepted by the real ALSA write call. Accepted buffers can later be discarded on seek. This does not capture kernel/DSP/transport/DAC/analog output or establish what was heard.</p><h2>Measured profile</h2><pre>__PROFILE__</pre><h2>Scoped checks</h2><table><thead><tr><th>Condition</th><th>Result</th><th>Scope</th></tr></thead><tbody>__ROWS__</tbody></table><h2>Retained limits</h2><p>The short edit fixture ran after the engine had advanced; it is not an early-edit qualification. A long-current fixture reached the intended state and passed. Decoder/file events can lead buffered presentation: <a href="https://github.com/42lizard/qoda-player/issues/20">playback occurrence timing remains a separate decision</a>.</p><p>Post-content XRUN was observed after final submission/drain. The confirmation check found no XRUN before the final submission, not a universal absence of underruns. Initial loader/control-poll failures and the corrected tag-analysis inefficiency remain documented.</p><ul>__UNVERIFIED__</ul><h2>Captured evidence</h2><ul>__LINKS__</ul><details><summary>Complete scope and reproduction guide</summary><pre>__GUIDE__</pre></details><p><a href="https://github.com/42lizard/qoda-player/issues/17">Canonical native qualification</a></p></main></html>'''
for k,v in [('__PASSED__',str(passed)),('__TOTAL__',str(len(checks))),('__ATTEMPT__',html.escape(attempt['status'])),('__PROFILE__',profile),('__ROWS__',rows),('__UNVERIFIED__',unverified),('__LINKS__',links),('__GUIDE__',guide)]:page=page.replace(k,v)
(E/'report.html').write_text(page)
